`;function i1(e,t,n,r){const o=e.filter(f=>f.category==="lighting"&&f.type!=="hazer").sort((f,h)=>(f.channel||999)-(h.channel||999)),i=e.filter(f=>f.type==="batten"),s=new Date().toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric"}),d=o.map(f=>{var C;const h=i.find(x=>x.id===f.battenId),g=un.find(x=>x.code===f.gelCode)||{code:"Open",name:"Open White",hex:"#ffffff"},w=((f.x||0)/B).toFixed(1),k=((f.y||0)/B).toFixed(1);return`
      <tr>
